result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/validator.py", "content": "#!/usr/bin/env python3
"""Question-bank JSON validator.

Schema (enforced by hand, no jsonschema dependency):

Top level:
  bank_id    : str matching ^[a-z0-9_]+$
  questions  : non-empty list of question objects

Each question:
  id     : non-empty str, unique across the whole list
  type   : one of "mc" | "numeric" | "short"
  prompt : non-empty str

Per type:
  mc      : "choices" (list of 3-6 unique non-empty strings)
            "answer"  (int index into choices, in range)
  numeric : "answer"    (number)
            "tolerance" (optional, number >= 0)
  short   : "accepted"  (non-empty list of non-empty strings)

collects ALL problems (never stops at the first) as dotted paths like
"questions[3].choices: duplicate values: 'x'". Exits 0 when valid,
1 when problems were found, 2 on usage/input errors.
"""

from __future__ import annotations

import json
import re
import sys

BANK_ID_RE = re.compile(r"^[a-z0-9_]+$")
QUESTION_TYPES = ("mc", "numeric", "short")


def _is_number(value) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _dupes(values: list) -> list:
    """Values that appear more than once, first-seen order preserved."""
    seen, dups = set(), []
    for v in values:
        if v in seen and v not in dups:
            dups.append(v)
        seen.add(v)
    return dups


def validate(bank) -> list[str]:
    """Return a list of ALL problems, each formatted as '<path>: <message>'."""
    if not isinstance(bank, dict):
        return ["bank: top level must be a JSON object"]

    errors: list[str] = []

    bank_id = bank.get("bank_id")
    if not isinstance(bank_id, str) or not BANK_ID_RE.match(bank_id):
        errors.append(
            f"bank_id: must match ^[a-z0-9_]+$ (got {bank_id!r})"
        )

    questions = bank.get("questions")
    if not isinstance(questions, list) or not questions:
        errors.append("questions: must be a non-empty list")
        return errors  # cannot index into questions any further

    seen_ids: dict[str, int] = {}
    for i, q in enumerate(questions):
        errors.extend(_validate_question(i, q, seen_ids))
    return errors


def _validate_question(i: int, q, seen_ids: dict[str, int]) -> list[str]:
    p = f"questions[{i}]"
    if not isinstance(q, dict):
        return [f"{p}: must be a JSON object"]

    errors: list[str] = []

    # --- common fields -------------------------------------------------
    qid = q.get("id")
    if not isinstance(qid, str) or not qid:
        errors.append(f"{p}.id: must be a non-empty string")
    elif qid in seen_ids:
        errors.append(
            f"{p}.id: duplicate id {qid!r} (first used at questions[{seen_ids[qid]}])"
        )
    else:
        seen_ids[qid] = i

    prompt = q.get("prompt")
    if not isinstance(prompt, str) or not prompt:
        errors.append(f"{p}.prompt: must be a non-empty string")

    qtype = q.get("type")
    if qtype not in QUESTION_TYPES:
        errors.append(
            f"{p}.type: must be one of 'mc', 'numeric', 'short' (got {qtype!r})"
        )
        return errors  # type-specific checks are meaningless otherwise

    # --- per-type fields -----------------------------------------------
    if qtype == "mc":
        num_choices = None
        if "choices" not in q:
            errors.append(f"{p}.choices: required for mc questions")
        else:
            choices = q["choices"]
            shape_ok = (
                isinstance(choices, list)
                and 3 <= len(choices) <= 6
                and all(isinstance(c, str) and c for c in choices)
            )
            if not shape_ok:
                errors.append(
                    f"{p}.choices: must be a list of 3-6 non-empty strings"
                )
            else:
                num_choices = len(choices)
                dups = _dupes(choices)
                if dups:
                    errors.append(
                        f"{p}.choices: duplicate values: "
                        + ", ".join(repr(d) for d in dups)
                    )
        if "answer" not in q:
            errors.append(f"{p}.answer: required for mc questions")
        else:
            ans = q["answer"]
            if not isinstance(ans, int) or isinstance(ans, bool):
                errors.append(f"{p}.answer: must be an integer index into choices")
            elif num_choices is not None and not 0 <= ans < num_choices:
                errors.append(
                    f"{p}.answer: index {ans} out of range for {num_choices} choices"
                )

    elif qtype == "numeric":
        if "answer" not in q:
            errors.append(f"{p}.answer: required for numeric questions")
        elif not _is_number(q["answer"]):
            errors.append(f"{p}.answer: must be a number")
        if "tolerance" in q:
            tol = q["tolerance"]
            if not _is_number(tol) or tol < 0:
                errors.append(f"{p}.tolerance: must be a number >= 0")

    else:  # short
        if "accepted" not in q:
            errors.append(f"{p}.accepted: required for short questions")
        else:
            accepted = q["accepted"]
            if (
                not isinstance(accepted, list)
                or not accepted
                or not all(isinstance(s, str) and s for s in accepted)
            ):
                errors.append(
                    f"{p}.accepted: must be a non-empty list of non-empty strings"
                )
            else:
                dups = _dupes(accepted)
                if dups:
                    errors.append(
                        f"{p}.accepted: duplicate values: "
                        + ", ".join(repr(d) for d in dups)
                    )

    return errors


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print(f"usage: {argv[0]} <question-bank.json>", file=sys.stderr)
        return 2
    path = argv[1]
    try:
        with open(path, encoding="utf-8") as fh:
            bank = json.load(fh)
    except OSError as exc:
        print(f"error: cannot read {path}: {exc}", file=sys.stderr)
        return 2
    except json.JSONDecodeError as exc:
        print(f"error: {path} is not valid JSON: {exc}", file=sys.stderr)
        return 2

    errors = validate(bank)
    if errors:
        for err in errors:
            print(f"ERROR {err}")
        print(f"FAILED: {len(errors)} problem(s) in {path}")
        return 1
    print(f"OK: {path}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"})
