from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent))
from validator import validate  # noqa: E402

ROOT = Path(__file__).resolve().parent
VALID = ROOT / "fixtures" / "valid_bank.json"
INVALID = ROOT / "fixtures" / "invalid_bank.json"

# The exact 6 violations planted in fixtures/invalid_bank.json.
PLANTED = {
    "bank_id: must match ^[a-z0-9_]+$ (got 'Bad Bank')",
    "questions[1].choices: duplicate values: 'red', 'blue'",
    "questions[2].tolerance: must be a number >= 0",
    "questions[3].accepted: must be a non-empty list of non-empty strings",
    "questions[4].answer: index 7 out of range for 3 choices",
    "questions[5].prompt: must be a non-empty string",
}


def _load(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


class TestValidBank:
    def test_valid_fixture_passes_with_no_errors(self):
        assert validate(_load(VALID)) == []

    def test_minimal_valid_bank(self):
        bank = {
            "bank_id": "tiny_1",
            "questions": [
                {"id": "q1", "type": "numeric", "prompt": "1+1?", "answer": 2}
            ],
        }
        assert validate(bank) == []


class TestPlantedViolations:
    """fixtures/invalid_bank.json has exactly 6 planted violations."""

    def test_exactly_six_problems(self):
        errors = validate(_load(INVALID))
        assert len(errors) == 6

    def test_exact_paths_and_messages(self):
        errors = validate(_load(INVALID))
        assert set(errors) == PLANTED

    @pytest.mark.parametrize(
        "fragment",
        [
            "bank_id:",
            "questions[1].choices:",
            "questions[2].tolerance:",
            "questions[3].accepted:",
            "questions[4].answer:",
            "questions[5].prompt:",
        ],
    )
    def test_each_planted_path_is_reported(self, fragment):
        errors = validate(_load(INVALID))
        assert any(e.startswith(fragment) for e in errors), fragment


class TestDuplicateIds:
    def test_duplicate_ids_across_list_caught(self):
        bank = {
            "bank_id": "dupes",
            "questions": [
                {"id": "q1", "type": "numeric", "prompt": "a?", "answer": 1},
                {"id": "q2", "type": "short", "prompt": "b?", "accepted": ["x"]},
                {"id": "q1", "type": "mc", "prompt": "c?", "choices": ["1", "2", "3"], "answer": 0},
                {"id": "q1", "type": "numeric", "prompt": "d?", "answer": 4},
            ],
        }
        errors = validate(bank)
        # questions[2] and questions[3] reuse q1; both must be flagged,
        # and nothing else may be reported.
        dup_errors = [e for e in errors if ".id:" in e]
        assert len(dup_errors) == 2
        assert any(e.startswith("questions[2].id:") and "'q1'" in e for e in dup_errors)
        assert any(e.startswith("questions[3].id:") and "'q1'" in e for e in dup_errors)
        assert errors == dup_errors  # no unrelated noise

    def test_validator_collects_all_problems_not_just_first(self):
        bank = {"bank_id": "BAD!", "questions": []}
        errors = validate(bank)
        assert len(errors) == 2
        assert errors[0].startswith("bank_id:")
        assert errors[1].startswith("questions:")


class TestCli:
    def run_cli(self, path: Path) -> subprocess.CompletedProcess:
        return subprocess.run(
            [sys.executable, str(ROOT / "validator.py"), str(path)],
            capture_output=True,
            text=True,
        )

    def test_cli_accepts_valid_fixture(self):
        proc = self.run_cli(VALID)
        assert proc.returncode == 0
        assert proc.stdout.startswith("OK")

    def test_cli_rejects_invalid_fixture(self):
        proc = self.run_cli(INVALID)
        assert proc.returncode == 1
        assert "6 problem(s)" in proc.stdout
        assert "questions[1].choices" in proc.stdout

    def test_cli_usage_error(self):
        proc = subprocess.run(
            [sys.executable, str(ROOT / "validator.py")],
            capture_output=True,
            text=True,
        )
        assert proc.returncode == 2
